import {ORDERS, groupOrdersByStatus} from './orders';

describe('smoke', () => {
  it('renders the app shell and orders table without throwing', () => {
    const html = renderToString(
      <ThemeProvider theme="light">
        <App />
      </ThemeProvider>,
    );
    expect(html).toContain('Главная');
    expect(html).toContain('Пользователи');
    expect(html).toContain('Заказы');
    expect(html).toContain('Настройки');
    expect(html).toContain('ORD-1001');
    expect(html).toContain('Группировать по статусу');
  });

  it('groups all orders by status with no loss', () => {
    const groups = groupOrdersByStatus(ORDERS);
    expect(groups).toHaveLength(5);
    expect(groups.reduce((sum, g) => sum + g.orders.length, 0)).toBe(ORDERS.length);
    for (const g of groups) {
      expect(g.orders.every((o) => o.status === g.status)).toBe(true);
    }
  });
});

